<?php
namespace App\Http\Controllers;
use App\Models\Lead;use App\Services\AvondaleHubsolvService;use Illuminate\Http\JsonResponse;use Throwable;
class AvondaleHubsolvController extends Controller {public function send(Lead $lead,AvondaleHubsolvService $svc):JsonResponse{try{$check=$svc->preflight($lead);if(!$check['ready'])return response()->json(['success'=>false,'message'=>'Avondale checks failed. Nothing was sent.','errors'=>$this->errors($check)],422);$r=$svc->send($lead);return response()->json(['success'=>true,'message'=>'Sent to AV HUBS successfully. HubSolv client '.$r['client_id'].'; '.$r['debt_count'].' debts accepted.']);}catch(Throwable $e){report($e);return response()->json(['success'=>false,'message'=>$e->getMessage()],409);}}private function errors(array $c):array{$x=[];if($c['missing_fields'])$x[]='Missing/invalid client fields: '.implode(', ',$c['missing_fields']);if($c['missing_reference_ids'])$x[]='Missing debt references: '.implode(', ',$c['missing_reference_ids']);if($c['missing_creditor_ids'])$x[]='Debts missing creditor: '.implode(', ',$c['missing_creditor_ids']);if($c['invalid_balance_ids'])$x[]='Debts with invalid balance: '.implode(', ',$c['invalid_balance_ids']);if(($c['debt_count']??0)<1)$x[]='No debts found';return $x;}}
